export const W=1200,H=760;
export const stations=[
{id:'seats1',name:'Seat west guests',short:'WEST GUESTS',x:265,y:290,duration:4,cost:45},
{id:'seats2',name:'Seat east guests',short:'EAST GUESTS',x:935,y:290,duration:4,cost:45},
{id:'seats3',name:'Seat west donors',short:'WEST DONORS',x:265,y:510,duration:4,cost:45},
{id:'seats4',name:'Seat east donors',short:'EAST DONORS',x:935,y:510,duration:4,cost:45},
{id:'lights',name:'Power the lights',short:'LIGHTING',x:115,y:165,duration:6,cost:65},
{id:'podium',name:'Prepare the podium',short:'PODIUM',x:600,y:170,duration:6,cost:65},
{id:'gold',name:'Polish the gold',short:'GOLD FINISH',x:1090,y:165,duration:5,cost:50},
{id:'ribbon',name:'Cut the ceremonial ribbon',short:'RIBBON',x:1090,y:640,duration:4,cost:35},
{id:'catering',name:'Lure wildlife to the service exit',short:'CATERING CRATE',x:600,y:430,duration:3,cost:0},
{id:'applause',name:'Applause distraction',short:'APPLAUSE',x:115,y:640,duration:1,cost:0},
{id:'broadcast',name:'Begin the broadcast',short:'GO LIVE',x:600,y:650,duration:20,cost:0}];
export function createGame(seconds=300){return {mode:'playing',remaining:seconds,elapsed:0,prep:20,lunch:{triggered:false,phase:'waiting',progress:0,exitTime:0,rfk:{x:1145,y:425},animals:[{kind:'raccoon',x:1130,y:440},{kind:'goose',x:1140,y:475}]},patience:100,budget:600,player:{x:600,y:530},trump:{x:600,y:115,target:null,phase:'away',timer:0,last:null},tasks:Object.fromEntries(stations.map(s=>[s.id,{progress:0,done:false}])),complications:[],warning:null,distraction:0,distractionTarget:null,cooldown:0,ribbonCooldown:0,work:null,event:'',eventId:0,won:false};}
export function say(g,text){g.event=text;g.eventId++;}
export function ready(g){return stations.filter(s=>!['applause','broadcast','catering'].includes(s.id)).every(s=>g.tasks[s.id].done);}
export function nearest(g){let near=null,dist=90;for(const s of stations){let d=Math.hypot(g.player.x-s.x,g.player.y-s.y);if(d<dist){near=s;dist=d;}}return near;}
export function distract(g,id){g.distraction=id==='applause'?20:12;g.distractionTarget=id;if(id==='applause')g.cooldown=38;else g.ribbonCooldown=28;g.warning=null;if(g.prep<=0){g.trump.target=id;g.trump.phase='distracted-approach';g.trump.timer=0;}say(g,id==='applause'?'“Finally. A machine that understands the assignment.”':'“A ribbon? For me? We must commemorate this commemoration.”');}
function choose(g){let priority=['podium',...(!g.tasks.gold.done?['gold']:[]),'ribbon','lights','gold'];return priority.find(id=>id!==g.trump.last&&!g.complications.some(c=>c.id===id))||null;}
function advanceAttention(g,dt){const b=g.trump;if(g.prep>0){g.prep=Math.max(0,g.prep-dt);if(g.prep===0){b.phase='idle';say(g,'THE BOSS HAS ARRIVED. Everything continues to be fine.');}return;}
if(g.distraction>0&&g.distractionTarget){if(!b.phase.startsWith('distracted')){b.target=g.distractionTarget;b.phase='distracted-approach';g.warning=null;}}
else if(b.phase.startsWith('distracted')){b.phase='idle';b.target=null;g.distractionTarget=null;}
if(b.phase==='idle'){b.timer=Math.max(0,b.timer-dt);if(b.timer===0&&g.complications.length<2){const id=choose(g);if(id){b.target=id;b.phase='noticing';b.timer=5;g.warning={id};say(g,'HEADS UP: he has noticed the '+stations.find(s=>s.id===id).short.toLowerCase()+'. Five seconds to redirect him.');}}}
else if(b.phase==='noticing'){b.timer-=dt;if(b.timer<=0){b.phase='approach';g.warning={id:b.target};}}
else if(b.phase==='approach'||b.phase==='distracted-approach'){const dest=stations.find(s=>s.id===b.target),tx=dest.x+(dest.x<600?65:-65),ty=dest.y+65,d=Math.hypot(tx-b.x,ty-b.y);if(d>5){const step=Math.min(d,62*dt);b.x+=(tx-b.x)/d*step;b.y+=(ty-b.y)/d*step;}else{b.phase=b.phase==='approach'?'occupied':'distracted';b.timer=3;}}
else if(b.phase==='occupied'){b.timer-=dt;if(b.timer<=0){const id=b.target;if(g.complications.length<2&&!g.complications.some(v=>v.id===id)){g.complications.push({id,progress:0});say(g,({gold:'“The gold needs to be more gold. People are saying beige.”',podium:'“Raise the microphone. My ideas are very tall.”',ribbon:'“That ribbon looks already cut. Give it a future.”',lights:'“Lighting should flatter me from all twelve directions.”'})[id]);}b.last=id;b.phase='idle';b.timer=7;g.warning=null;}}
}
function advanceLunch(g,dt){const l=g.lunch;if(!l.triggered&&g.prep<=0&&(g.elapsed>=70||stations.filter(s=>!['applause','broadcast','catering'].includes(s.id)&&g.tasks[s.id].done).length>=4)){l.triggered=true;l.phase='active';say(g,'RFK JR: “I have catered lunch. It has brought its own opinions.”');}if(l.phase==='active'){l.rfk.x=Math.max(1050,l.rfk.x-35*dt);l.animals.forEach((a,i)=>{const tx=i===0?935+Math.sin(g.elapsed*.4)*45:600+Math.sin(g.elapsed*.65)*145,ty=i===0?500:590;const d=Math.hypot(tx-a.x,ty-a.y);if(d>3){a.x+=(tx-a.x)/d*(i?47:38)*dt;a.y+=(ty-a.y)/d*(i?47:38)*dt;}});g.patience=Math.max(0,g.patience-.14*dt);}else if(l.phase==='leaving'){l.exitTime-=dt;l.animals.forEach((a,i)=>{a.x+=(1160-a.x)*dt*.9;a.y+=((450+i*30)-a.y)*dt*.9;});l.rfk.x+=25*dt;if(l.exitTime<=0){l.phase='resolved';say(g,'Lunch has safely returned to its natural habitat: the loading dock.');}}}
export function tick(g,dt,input={}){if(g.mode!=='playing')return;dt=Math.min(dt,.1);g.remaining-=dt;g.elapsed+=dt;if(g.trump.phase==='distracted')g.distraction=Math.max(0,g.distraction-dt);g.cooldown=Math.max(0,g.cooldown-dt);g.ribbonCooldown=Math.max(0,g.ribbonCooldown-dt);
let dx=(input.right?1:0)-(input.left?1:0),dy=(input.down?1:0)-(input.up?1:0),len=Math.hypot(dx,dy);if(len){g.player.x=Math.max(72,Math.min(1128,g.player.x+dx/len*220*dt));g.player.y=Math.max(128,Math.min(697,g.player.y+dy/len*220*dt));}
const s=nearest(g);g.work=null;if(input.work&&s){const issue=g.complications.find(c=>c.id===s.id),task=g.tasks[s.id];if(s.id==='catering'){if(g.lunch.phase==='active'){g.lunch.progress+=dt;g.work={id:s.id,value:g.lunch.progress/3};if(g.lunch.progress>=3){g.lunch.phase='leaving';g.lunch.exitTime=5;say(g,'Crate bait deployed. Please allow five seconds for lunch to depart.');}}}else if(s.id==='applause'){if(g.cooldown<=0)distract(g,'applause');}else if(s.id==='ribbon'&&task.done&&!issue){if(g.ribbonCooldown<=0)distract(g,'ribbon');}else if(s.id==='broadcast'&&(!ready(g)||g.complications.length||['active','leaving'].includes(g.lunch.phase))){const line=['active','leaving'].includes(g.lunch.phase)?'Escort the lunch delivery out before going live.':!ready(g)?'Finish the eight preparations before going live.':'Resolve the orange requests before going live.';if(g.event!==line)say(g,line);}else if(issue||!task.done){const target=issue||task;target.progress+=dt;g.work={id:s.id,value:target.progress/(issue?4:s.duration)};if(target.progress>=(issue?4:s.duration)){if(issue){g.complications=g.complications.filter(c=>c!==issue);g.patience=Math.min(100,g.patience+7);say(g,'Crisis resolved. Put it under “miscellaneous excellence.”');}else{task.done=true;g.budget-=s.cost;say(g,s.id==='broadcast'?'The broadcast is live. The room looks almost intentional.':'✓ '+s.name+'. One fewer thing to explain.');if(s.id==='broadcast'){g.mode='won';g.won=true;return;}}}}}
advanceAttention(g,dt);advanceLunch(g,dt);g.patience=Math.max(0,g.patience-dt*g.complications.length*.20);if(g.remaining<=0||g.patience<=0){g.mode='lost';g.lossReason=g.patience<=0?'Presidential patience reached zero.':'The shift clock ran out.';say(g,g.lossReason);}}
